    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (S[i][j] == 'B') buildings.push_back({i, j});
        }
    }

    int ans = 0;
    for (int i = 0; i < (int)buildings.size(); ++i) {
        for (int j = i + 1; j < (int)buildings.size(); ++j) {
            ans = max(ans,
                      abs(buildings[i].first - buildings[j].first) +
                      abs(buildings[i].second - buildings[j].second));
        }
    }

    cout << ans << '\n';
