import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();

        int max1 = Integer.MIN_VALUE, min1 = Integer.MAX_VALUE; // i + j
        int max2 = Integer.MIN_VALUE, min2 = Integer.MAX_VALUE; // i - j

        for (int i = 0; i < H; i++) {
            String s = fs.next();
            for (int j = 0; j < W; j++) {
                if (s.charAt(j) == 'B') {
                    int a = i + j;
                    int b = i - j;
                    if (a > max1) max1 = a;
                    if (a < min1) min1 = a;
                    if (b > max2) max2 = b;
                    if (b < min2) min2 = b;
                }
            }
        }

        int ans = Math.max(max1 - min1, max2 - min2);
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

